import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Solid ink primary, hairline ghost, or borderless subtle. One primary per view. */
  variant?: "primary" | "ghost" | "subtle";
  /** Icon buttons stay square at every breakpoint. Supply an accessible name. */
  size?: "default" | "sm" | "icon";
  /** Flush into a ButtonGroup: no own stroke, one ink seam. */
  grouped?: boolean;
}

const styles = stylex.create({
  base: {
    boxSizing: "border-box",
    minWidth: vlak.hit,
    fontFamily: "inherit",
    letterSpacing: "-0.01em",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: "0.5rem",
    cursor: {
      default: "pointer",
      ":disabled": "not-allowed",
    },
    height: {
      default: vlak.controlH,
      [mq.phone]: vlak.controlH,
    },
    minHeight: {
      default: null,
      [mq.phone]: vlak.hit,
    },
    width: {
      default: null,
      [mq.phone]: "100%",
    },
    fontSize: vlak.controlFs,
    paddingInline: {
      default: "1.375rem",
      [mq.phone]: "1.25rem",
    },
    borderWidth: vlak.hairline,
    borderStyle: "solid",
    borderRadius: {
      default: vlak.radiusSm,
      [mq.phone]: vlak.radiusSm,
    },
    transition: {
      default: vlak.transition,
      [mq.reduce]: "none",
    },
    /* Hover and disabled are opacity on paper; in forced colors they become system colors instead. */
    opacity: {
      default: 1,
      ":hover:not(:disabled):not([aria-disabled='true']):not([aria-pressed='true']):not([aria-selected='true']):not([aria-current])": { default: null, [mq.hover]: 0.85 },
      ":disabled": 0.4,
      [mq.forcedColors]: {
        default: 1,
        ":hover:not(:disabled):not([aria-disabled='true']):not([aria-pressed='true']):not([aria-selected='true']):not([aria-current])": { default: null, [mq.hover]: 1 },
        ":disabled": 1,
      },
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  primary: {
    fontWeight: 600,
    backgroundColor: {
      default: vlak.ink,
      [mq.forcedColors]: "ButtonFace",
    },
    color: {
      default: vlak.paper,
      [mq.forcedColors]: {
        default: "ButtonText",
        ":disabled": "GrayText",
      },
    },
    borderColor: {
      default: "transparent",
      [mq.forcedColors]: {
        default: "ButtonText",
        ":disabled": "GrayText",
      },
    },
  },
  ghost: {
    transition: {
      default: vlak.transition,
      [mq.reduce]: "none",
