  grouped: {
    height: "auto",
    minHeight: vlak.hit,
    width: {
      default: null,
      [mq.phone]: null,
    },
    borderWidth: 0,
    borderRadius: 0,
    margin: 0,
    flexGrow: {
      default: null,
      [mq.phone]: 1,
    },
    minWidth: {
      default: 0,
      [mq.phone]: 0,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": -2,
    },
  },
  groupedGhost: {
    transition: {
      default: vlak.transition,
